import { IconButton } from '@advui/core'
import { SettingsIcon } from '@advui/icons'

export default function IconButtonBasic() {
  return <IconButton aria-label="Settings" icon={<SettingsIcon />} />
}

import { HStack, IconButton } from '@advui/core'
import { HeartIcon, PlusIcon, SearchIcon, TrashIcon } from '@advui/icons'

export default function IconButtonVariants() {
  return (
    <HStack gap="$2">
      <IconButton aria-label="Search" icon={<SearchIcon />} />
      <IconButton aria-label="Add" variant="outline" icon={<PlusIcon />} />
      <IconButton aria-label="Favorite" variant="secondary" circular icon={<HeartIcon />} />
      <IconButton aria-label="New" variant="default" icon={<PlusIcon />} />
      <IconButton aria-label="Delete" variant="destructive" icon={<TrashIcon />} />
    </HStack>
  )
}

import { HStack, IconButton } from '@advui/core'
import { BellIcon } from '@advui/icons'

export default function IconButtonSizes() {
  return (
    <HStack gap="$2" alignItems="center">
      <IconButton aria-label="Notifications" variant="outline" size="sm" icon={<BellIcon />} />
      <IconButton aria-label="Notifications" variant="outline" size="md" icon={<BellIcon />} />
      <IconButton aria-label="Notifications" variant="outline" size="lg" icon={<BellIcon />} />
    </HStack>
  )
}
